function runExamFailureDelayRegression() {
  const { api, elements, window } = createHarness();
  api.setRandomSeed(5150);
  chooseRoute(api, '路径五 · 读书应举');
  api.patchState({
    识字: true,
    铜钱: 420,
    存米: 2,
    家族: 64,
    白银: 1,
    负债银: 0,
    本年保帖底样次数: 1,
    举业累计保帖底样次数: 1
  });
  api.setRandomSequence(new Array(120).fill(0.99));
  api.enterPhase('civilExam');

  let guard = 0;
  while (api.getPhase() === 'civilExam' && guard < 60) {
    const state = api.getState();
    if (examXun(state) === 1) {
      if ((state.举季 || 1) <= 2 && (state.投塾进度 || 0) >= 2 && (state.本年保帖底样次数 || 0) <= 0) {
        pickByPlan(api, ['e_tutor', 'e_guarantee_prep', 'e_home']);
      } else {
        pickByPlan(api, ['e_enroll', 'e_tutor', 'e_home']);
      }
    }
    else if (examXun(state) === 2) {
      if ((state.举季 || 1) <= 2 && (state.本年保帖底样次数 || 0) <= 0) pickByPlan(api, ['e_guarantee_prep', 'e_essay', 'e_copy']);
      else if ((state.举季 || 1) >= 3 && (state.保结进度 || 0) < 2) pickByPlan(api, ['e_guarantee', 'e_copy']);
      else pickByPlan(api, ['e_essay', 'e_copy']);
    }
    else if ((state.举季 || 1) >= 3 && (state.保结进度 || 0) >= 2 && !state.本年下场) pickByPlan(api, ['e_exam']);
    else pickByPlan(api, ['e_copy', 'e_home']);
    api.commit();
    api.next();
    guard += 1;
  }

  const phase = api.getPhase();
  const state = clone(api.getState());
  const lifeProfile = clone(api.getLifeProfile());
  const childbearing = clone(api.getChildbearingProfile());
  const marriageHtml = normalizeHtml(elements.get('stage').innerHTML);
  const phaseTrace = clone(api.getPhaseTrace ? api.getPhaseTrace() : []);
  const okChecks = {
    phase: phase === 'marriage',
    shengyuan: state.生员身份 === false,
    outcome: state.举业结局 === '塾馆教读',
    delay: state.举业累计延婚牵扯 >= 8,
    body: state.举业累计身子亏空 >= 3,
    ageAdj: state._marriageAgeAdj >= 3,
    marriageAge: lifeProfile.marriageAge === 27 + state._marriageAgeAdj,
    fertility: lifeProfile.fertilityTag === 'lateStrict',
    childbearing: childbearing.label === '窄窗',
    htmlAge: marriageHtml.includes(`婚配年龄=${lifeProfile.marriageAge}`),
    htmlWindow: marriageHtml.includes(`婚育窗口=${childbearing.label}`),
    htmlOutcome: marriageHtml.includes(`举业结局=${state.举业结局}`),
    htmlFails: marriageHtml.includes(`累计落第=${state.举业累计落第次数}`),
    htmlDelay: marriageHtml.includes(`累计延婚=${state.举业累计延婚牵扯}`),
    htmlBody: marriageHtml.includes(`累计身耗=${state.举业累计身子亏空}`),
    phases: includesOrderedPhases(phaseTrace, ['civilExam', 'marriage']),
    inv: (window.__INV || []).length === 0
  };

  return {
    phase,
    examState: {
      举业结局: state.举业结局,
      童试层级: state.童试层级,
      本年应试结果: state.本年应试结果,
      本年落第次数: state.本年落第次数,
      举业累计落第次数: state.举业累计落第次数,
      举业累计延婚牵扯: state.举业累计延婚牵扯,
      举业累计身子亏空: state.举业累计身子亏空,
      负债银: state.负债银,
      _marriageAgeAdj: state._marriageAgeAdj,
      生员身份: state.生员身份
    },
    lifeProfile: {
      marriageAge: lifeProfile.marriageAge,
      householdAge: lifeProfile.householdAge,
      fertilityTag: lifeProfile.fertilityTag
    },
    childbearing: {
      label: childbearing.label,
      note: childbearing.note
    },
    marriageHtml,
    phaseTrace: phaseTrace.map((step) => `${step.phase}@${step.age}`).join(' → '),
    okChecks,
    ok: Object.values(okChecks).every(Boolean)
  };
}

